/**
 * `ccb attach <short>` — interactive bridge to a PTY-mode bg session.
 *
 * Mirrors ant 4649.js aM3 + Yg client side. Connects to the PTY
 * host's Unix socket via `createPtyAdopter`, sets local TTY into raw
 * mode, forwards stdin keystrokes as DATA frames, paints DATA frames
 * back to stdout, and propagates SIGWINCH as resize ctrl frames.
 *
 * Detach key: Ctrl+Q (0x11). Pressing it disposes the adopter and
 * exits the client process WITHOUT killing the bg session — the host
 * keeps running, ready for a future re-attach. This matches ant's
 * detach semantics (clients are decoupled from session lifecycle).
 *
 * Exit code:
 *   0 — clean detach (Ctrl+Q) or session exited normally (code 0)
 *   non-zero — session exited with that code
 *
 * @dynamicRequire
 */

import { logEvent } from '@thyrox/local-observability'
import { createDecModeTracker } from './decModeTracker.js'
import { createPtyAdopter, type PtyAdopter } from './ptyAdopter.js'

const DETACH_KEY_BYTE = 0x11 // Ctrl+Q
/**
 * APC detach sentinel — ant 4176.js `aNH = "\x1b_cc-daemon-detach\x1b\\"`.
 * Emitted by the inner REPL's `$1H()` (4177.js) when the user presses
 * left-arrow on an empty prompt while running as a bg session. runAttach
 * scans incoming PTY data for it, paints any pre-sentinel output, then
 * detaches without killing the bg worker.
 *
 * APC = Application Program Command: ESC `_` <payload> ESC `\` (ST).
 */
const DETACH_APC_SENTINEL = Buffer.from('\x1b_cc-daemon-detach\x1b\\')

/**
 * `PzH()` equivalent from ant 2281.js — written to stdout when the
 * attach client first connects (and caller is NOT already in alt-screen):
 *   Go_ = \x1b[?1049h   ALT_SCREEN_CLEAR set (enter alt, clear scrollback)
 *   qG  = \x1b[2J       Clear entire screen
 *   _f  = \x1b[H        Move cursor to home
 * (`Fl()` for kitty keyboard is omitted — ccb doesn't ship a kitty kbd
 * protocol decoder, so emitting kitty CSI would corrupt later key parse.)
 */
const ALT_SCREEN_ENTER = '\x1b[?1049h\x1b[2J\x1b[H'

/**
 * `KE()` equivalent from ant 2281.js — written on detach when not
 * alreadyInAlt:
 *   Ss   = \x1b[<u      disable kitty keyboard protocol  (no-op if not in)
 *   qh9  = \x1b[?1049l  ALT_SCREEN_CLEAR reset (exit alt-screen)
 *   v9H  = \x1b[>4m     disable xterm modifyOtherKeys mode
 */
const ALT_SCREEN_EXIT = '\x1b[<u\x1b[?1049l\x1b[>4m'

/**
 * Longest-suffix-prefix match. Returns the length `k` such that the last
 * `k` bytes of `buf` equal the first `k` bytes of `needle` — used to
 * detect the start of a sentinel that straddles a chunk boundary.
 *
 * Source: ant 4767.js `Pg8`.
 */
function suffixMatchLen(buf: Buffer, needle: Buffer): number {
  const max = Math.min(buf.length, needle.length - 1)
  outer: for (let k = max; k > 0; k--) {
    const start = buf.length - k
    for (let i = 0; i < k; i++) {
      if (buf[start + i] !== needle[i]) continue outer
    }
    return k
  }
  return 0
}

/**
 * Open a PTY socket attach session. Resolves when the bg session
 * exits OR the user presses Ctrl+Q. Caller is responsible for
 * confirming the socket path exists; we'll surface a clear error if
 * connect fails.
 */
export async function runAttach(
  socketPath: string,
  short: string,
): Promise<void> {
  let adopter: PtyAdopter | undefined
  let restoreTty: (() => void) | undefined
  let exitCode = 0
  let detached = false
  const startedAt = Date.now()
  let firstFrameAt = 0
  const decModes = createDecModeTracker()
  logEvent('tengu_bg_attach', { short })

  // stdin source. Two cases:
  //
  //   (A) Came from in-process FleetView (left-arrow → agents → right-arrow
  //       attach). FleetView destroy()s Bun's process.stdin to give its rust
  //       reader sole ownership of fd 0, so process.stdin is dead here — its
  //       'data'/setRawMode are no-ops. We must read fd 0 through the SAME
  //       rust reader (stdin-napi). Detected via process.stdin.destroyed.
  //
  //   (B) Standalone `ccb attach <short>` from the user's shell. Bun's
  //       process.stdin is alive; use it directly.
  //
  // Both feed the same onData handler below.
  const stdinDestroyed = (process.stdin as NodeJS.ReadStream & {
    destroyed?: boolean
  }).destroyed === true
  let nativeReaderStop: (() => void) | undefined

  // Local TTY raw-mode setup. Without this, the local terminal would
  // do its own line-buffering + Ctrl+C → SIGINT → kill the attach
  // client's process (which we don't want). Raw mode also lets us
  // detect the Ctrl+Q sentinel. In case (A) the rust reader owns termios,
  // so we skip the Node setRawMode (it would throw on a destroyed stream).
  if (!stdinDestroyed && process.stdin.isTTY && process.stdin.setRawMode) {
    const wasRaw = process.stdin.isRaw
    process.stdin.setRawMode(true)
    restoreTty = () => {
      try {
        if (process.stdin.setRawMode) process.stdin.setRawMode(wasRaw)
      } catch {
        // best-effort
      }
    }
  }

  // Alt-screen ENTER is handled by the caller (agentsFleet loop) so
  // the swap brackets the unmount-FleetView → spawn-runAttach gap.
  // For the standalone `ccb attach <short>` CLI, the caller is the
  // user's shell and the inner REPL's own alt-screen toggle is what
  // the user sees — we write ALT_SCREEN_ENTER below as a fallback
  // only when stdin/stdout look like a TTY but no caller-managed
  // swap has happened yet (heuristic: `CCB_ATTACH_OWNED_ALT_SCREEN`
  // env set by the loop).
  if (!process.env.CCB_ATTACH_OWNED_ALT_SCREEN) {
    process.stdout.write(ALT_SCREEN_ENTER)
  }

  // Open adopter against the host socket.
  adopter = createPtyAdopter(socketPath)

  // Forward local stdin keystrokes to the PTY. Two sources (see stdinDestroyed
  // above): the rust reader (case A — FleetView destroy()d process.stdin) or
  // Bun's process.stdin 'data' event (case B — standalone `ccb attach`). Both
  // feed onData. We use 'data' (flowing), not 'readable'+read(): on public Bun,
  // process.stdin's 'readable' is unreliable for raw-mode keystrokes after an
  // Ink unmount (ant uses 'readable' only because its bun-internal fork patches
  // this). Stop reading local stdin — works for both sources. Idempotent.
  const stopStdin = (): void => {
    if (nativeReaderStop) {
      nativeReaderStop()
      nativeReaderStop = undefined
    } else {
      process.stdin.removeListener('data', onData)
    }
  }
  const handleByteChunk = (chunkBuf: Buffer): void => {
    // Scan for Ctrl+Q. Pass everything before the sentinel through;
    // anything after is dropped because we're detaching.
    const idx = chunkBuf.indexOf(DETACH_KEY_BYTE)
    if (idx === -1) {
      adopter!.write(chunkBuf)
      return
    }
    if (idx > 0) {
      adopter!.write(chunkBuf.subarray(0, idx))
    }
    detached = true
    stopStdin()
  }
  const onData = (chunk: Buffer | string): void => {
    const buf = Buffer.isBuffer(chunk)
      ? chunk
      : Buffer.from(chunk as string, 'utf8')
    handleByteChunk(buf)
  }
  if (stdinDestroyed) {
    // Case (A): read fd 0 through the rust reader (Bun's process.stdin is
    // destroyed by FleetView). The reader owns termios + reads on its own
    // thread, feeding onData with each chunk. redirect_fd0=false: fd 0 is
    // free (Bun no longer reads it), so no dup2 redirect needed.
    const { startReader } = await import('@thyrox/stdin-napi')
    let handle: { stop(): void } | undefined
    try {
      handle = startReader(false, onData)
    } catch {
      // reader failed to start; leave handle undefined (no input forwarding)
    }
    nativeReaderStop = () => {
      try {
        handle?.stop()
      } catch {
        // best-effort
      }
    }
  } else {
    process.stdin.on('data', onData)
    process.stdin.ref()
    process.stdin.resume()
  }

  // Frame-boundary buffer: hold all incoming PTY bytes until we see
  // the inner REPL emit a frame boundary marker — either:
  //   `\x1b[2J`        clear-entire-screen (legacy full-repaint marker)
  //   `\x1b[H\x1b[2K`  cursor-home + erase-line (ant's `P` sentinel — see
  //                    5288.js daemon attach: `let P = _f + zzH`).
  // Both indicate the start of a complete frame. Until one arrives the
  // alt-screen retains the outer FleetView pixels (preserved by
  // `handoffAltScreen` — see agentsFleet.ts). When one arrives we flush
  // FROM it onwards AND wrap the flush in `BSU…ESU` to force the
  // terminal (when DEC 2026 is supported, e.g. iTerm2) to apply the
  // whole transition atomically — even if the inner's own framing
  // didn't wrap THIS chunk in BSU/ESU. Without DEC 2026 it's a no-op.
  //
  // Source: ant 5288.js attach handler —
  //   if (qH.includes(qG) || qH.includes(P)) { write(qH or r) }
  // where qG=\x1b[2J, P=\x1b[H\x1b[2K, plus the BSU/ESU wrap that ant
  // Ink already inlines around every render (terminal.ts ant equivalent).
  const FRAME_CLEAR = Buffer.from('\x1b[2J')
  const FRAME_HOME_ERASE = Buffer.from('\x1b[H\x1b[2K')
  const BSU = Buffer.from('\x1b[?2026h')
  const ESU = Buffer.from('\x1b[?2026l')
  // Source: ant 4767.js `Md` write logic — line:
  //   K.write(_.alreadyInAlt ? ru + Fl() + YH : PzH() + YH + (m ? ru : "") + ...)
  // When `alreadyInAlt` is true, ant DOES NOT buffer waiting for a
  // frame-boundary marker. It writes the ack DEC modes immediately and
  // then paints incoming PTY bytes the moment they arrive. The trick:
  //
  //   - The alt-screen buffer already has the outer FleetView pixels
  //     (preserved by `handoffAltScreen()` — no \x1b[?1049l was emitted).
  //   - The inner REPL's first paint is INVISIBLE escape codes (DEC
  //     mode sets/resets) until it finally emits its own \x1b[2J or
  //     home-erase as part of its first render. Those invisible codes
  //     change terminal state, not the visible cells.
  //   - When the inner's first render does fire, its CLEAR+CELLS pair
  //     overwrites the FleetView pixels in a single coherent paint.
  //
  // ccb previously buffered everything until a frame-boundary marker
  // appeared, which meant during the inner REPL's boot delay (~1-2s of
  // bun + bundle load + first-render) NOTHING was painted. With proper
  // handoff the alt-screen WOULD still show FleetView pixels — but only
  // if no other write happened. Inner-REPL boot emits non-clearing
  // escape codes that are safely ignored by the terminal; buffering
  // them deferred the natural transition without benefit.
  //
  // Set `attachBuffer = null` initially when CCB_ATTACH_OWNED_ALT_SCREEN
  // is set so we mirror ant exactly (no buffer). Standalone `ccb attach`
  // (no env var) keeps the buffer because runAttach itself wrote
  // `\x1b[?1049h\x1b[2J\x1b[H` and the screen is blank — buffering until
  // first frame avoids painting partial mode-setup garbage.
  const ownedAltScreen = !!process.env.CCB_ATTACH_OWNED_ALT_SCREEN
  let attachBuffer: Buffer | null = ownedAltScreen ? null : Buffer.alloc(0)

  // Render incoming PTY output to local stdout. Track DEC private modes
  // (ant 4638.js Yg) so detach can restore local terminal state. Also
  // scan for ant's APC detach sentinel (ant 4177.js $1H → 4176.js w_H).
  //
  // Source: ant 4767.js `o(s)` — buffers a partial-match tail across
  // chunk boundaries so the sentinel isn't missed across packets.
  let pendingTail: Buffer = Buffer.alloc(0)
  const handleLivePaint = (incoming: Buffer): void => {
    if (firstFrameAt === 0) {
      firstFrameAt = Date.now()
      logEvent('tengu_bg_attach_first_frame', {
        ms: String(firstFrameAt - startedAt),
      })
    }
    const wH =
      pendingTail.length > 0 ? Buffer.concat([pendingTail, incoming]) : incoming

    const idx = wH.indexOf(DETACH_APC_SENTINEL)
    if (idx >= 0) {
      if (idx > 0) {
        const before = wH.subarray(0, idx)
        decModes.feed(before)
        process.stdout.write(before)
      }
      pendingTail = Buffer.alloc(0)
      detached = true
      stopStdin()
      return
    }

    const k = suffixMatchLen(wH, DETACH_APC_SENTINEL)
    if (wH.length > k) {
      const paint = wH.subarray(0, wH.length - k)
      decModes.feed(paint)
      process.stdout.write(paint)
    }
    pendingTail = k > 0 ? Buffer.from(wH.subarray(wH.length - k)) : Buffer.alloc(0)
  }

  const dataSub = adopter.onData(chunk => {
    const incoming = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk, 'binary')

    if (attachBuffer !== null) {
      attachBuffer = Buffer.concat([attachBuffer, incoming])
      const clearIdx = attachBuffer.indexOf(FRAME_CLEAR)
      const homeEraseIdx = attachBuffer.indexOf(FRAME_HOME_ERASE)
      let markerIdx = -1
      if (clearIdx >= 0 && homeEraseIdx >= 0) {
        markerIdx = Math.min(clearIdx, homeEraseIdx)
      } else if (clearIdx >= 0) {
        markerIdx = clearIdx
      } else if (homeEraseIdx >= 0) {
        markerIdx = homeEraseIdx
      }
      if (markerIdx === -1) {
        // No frame boundary yet — keep buffering. Cap at 1 MiB so a
        // misbehaving stream doesn't OOM us.
        if (attachBuffer.length > 1024 * 1024) {
          attachBuffer = attachBuffer.subarray(attachBuffer.length - 1024 * 1024)
        }
        return
      }
      // Found a boundary — flush from it. Wrap in BSU/ESU so terminals
      // supporting DEC 2026 apply the whole `clear+cells` transition
      // atomically (FleetView pixels → session UI with zero
      // intermediate paint). On terminals without sync support the
      // wrap is harmless (BSU/ESU are just unknown DECSET codes).
      const flushBytes = attachBuffer.subarray(markerIdx)
      attachBuffer = null
      handleLivePaint(Buffer.concat([BSU, flushBytes, ESU]))
      return
    }

    handleLivePaint(incoming)
  })

  // Resolve when the host signals exit OR we detach.
  const exitPromise = new Promise<void>(resolve => {
    const exitSub = adopter!.onExit(info => {
      exitCode = info.exitCode === -1 ? 1 : info.exitCode
      exitSub.dispose()
      resolve()
    })
  })

  // Resize propagation: when the local terminal changes size, send
  // a resize ctrl frame so the host PTY matches.
  const initialResize = (): void => {
    const cols = process.stdout.columns
    const rows = process.stdout.rows
    if (cols && rows) adopter!.resize(cols, rows)
  }
  initialResize()
  const onResize = (): void => initialResize()
  process.stdout.on('resize', onResize)

  // ant 5164.js stall watchdog: if no first frame within
  // NO client-side first-frame/stall watchdog. Source: ant `dc` (4945.js)
  // has none — its only timeout is a 10s ACK timeout cleared the moment the
  // daemon's attach-ack arrives; after that the client never times out on
  // frame data. An idle worker (state.tempo=blocked, "send a prompt to
  // start") sits silent at its prompt and emits no frame, so a client-side
  // "no first frame in 30s → kill" watchdog MISFIRES on idle sessions and
  // tears the whole attach (and process) down at exactly 30s. ant avoids
  // this by (a) keeping stall detection on the DAEMON/host side, gated on
  // "did a forced repaint produce bytes", not on a blind client clock, and
  // (b) forcing the inner REPL to redraw on every attach so a frame always
  // arrives. ccb's host-side repaint-on-attach lives in ptyHost.ts; the
  // client just paints whatever the PTY sends, including nothing.
  // firstFrameAt below is kept for telemetry only (ant's f() does the same).

  // Wait for either exit or detach.
  const detachPromise = new Promise<void>(resolve => {
    const checker = setInterval(() => {
      if (detached) {
        clearInterval(checker)
        resolve()
      }
    }, 25)
    checker.unref()
  })

  await Promise.race([exitPromise, detachPromise])

  // ant 4638.js: emit DEC mode restore so the local terminal isn't
  // stuck in mouse-mode / bracketed-paste / etc. carried over from the
  // inner REPL.
  const restore = decModes.restoreSequence()
  if (restore) process.stdout.write(restore)

  // Alt-screen EXIT — only when we own the swap (standalone CLI).
  // FleetView caller exits alt itself after this returns.
  if (!process.env.CCB_ATTACH_OWNED_ALT_SCREEN) {
    process.stdout.write(ALT_SCREEN_EXIT)
  }

  // Cleanup.
  dataSub.dispose()
  process.stdout.removeListener('resize', onResize)
  stopStdin()
  // NOTE: do NOT pause stdin — the caller (fleetAttach loop) is about
  // to mount a fresh Ink root which needs an active readable stream.
  // The standalone `ccb attach` CLI exits process after this anyway,
  // so leaving stdin live is harmless there too.
  adopter.dispose()
  restoreTty?.()

  const outcome = detached ? 'detached' : 'exited'
  logEvent('tengu_bg_attach_outcome', {
    outcome,
    got_first_frame: String(firstFrameAt > 0),
    ms: String(Date.now() - startedAt),
  })

  // NOTE: callers from FleetView (fleetAttach) expect runAttach to
  // RETURN — process.exit would kill the outer FleetView too. The
  // standalone `ccb attach <short>` CLI path catches this in
  // attachHandler and exits cleanly. Detach/exit reasons are surfaced
  // via the returned outcome string so callers can decide.
  if (detached) {
    process.stderr.write(`\n[detached from ${short} — session keeps running]\n`)
    return
  }
  process.stderr.write(`\n[session ${short} exited with code ${exitCode}]\n`)
}

/**
 * PTY socket adopter — speaks the bg-pty-host wire protocol.
 *
 * Daemon-less ccb's `ccb attach <short>` opens this directly against
 * the PTY host's socket; a future Phase C+ daemon would also use it
 * for cross-process supervision. Mirrors ant 4704.js rj6, but trimmed
 * down: ccb has no daemon supervisor so the respawn-detection /
 * upgrade-tracking / roster-hooks branches are removed. What's kept:
 *
 *   - Connect with backoff (WXK=30 attempts, PXK=[100,250,500,1000,2000])
 *   - ENOENT detection (socket file gone) → caller-visible error
 *   - Hello-handshake receipt (capture replPid + version)
 *   - Buffer queue while disconnected (cap 2MB before drop)
 *   - Per-client backpressure: writableLength > 1 MiB → destroy
 *   - onData / onExit pub-sub callbacks
 *   - write / resize / kill / dispose API surface
 *   - SIGKILL escalation 5s after SIGTERM
 *
 * @dynamicRequire
 */

import { type Socket, connect } from 'node:net'

import {
  CTRL_TAG,
  DATA_TAG,
  type CtrlFrame,
  createFrameDecoder,
  encodeCtrlFrame,
  encodeDataFrame,
  FRAME_SIZE_CAP,
} from './ptyFrame.js'

const RECONNECT_BACKOFF_MS = [100, 250, 500, 1000, 2000] as const
const MAX_RECONNECT_ATTEMPTS = 30
const QUEUE_CAP_BYTES = 2 * FRAME_SIZE_CAP // 2 * qiH = 2 MiB
const CLIENT_BACKPRESSURE_BYTES = 1024 * 1024
const SIGTERM_GRACE_MS = 5000

export interface PtyAdopter {
  /** Currently-known REPL pid (from hello frame). 0 if not yet seen. */
  replPid(): number
  /** Currently-known REPL version (from hello frame). '' if not yet seen. */
  replVersion(): string
  /** Send raw bytes to the PTY (will be decoded as user input). Takes a
   *  Buffer, NOT a string: stdin bytes (esp. multi-byte UTF-8 like CJK) must
   *  pass through verbatim. A string round-trip (toString('binary') at the
   *  caller + Buffer.from(s,'utf8') here) double-encoded high bytes and
   *  corrupted CJK input. */
  write(b: Buffer): void
  /** Send a resize ctrl frame. */
  resize(cols: number, rows: number): void
  /** Send a kill ctrl frame. SIGTERM auto-escalates to SIGKILL after 5s. */
  kill(sig: 'SIGTERM' | 'SIGKILL'): void
  /** Tear down the adopter (closes socket, cancels timers). */
  dispose(): void
  /** Subscribe to PTY output (bytes from the host). */
  onData(cb: (chunk: Buffer) => void): { dispose: () => void }
  /** Subscribe to host exit notification. */
  onExit(
    cb: (info: { exitCode: number; signal?: string }) => void,
  ): { dispose: () => void }
  /** Subscribe to host heartbeat ctrl-frames (every 5s while alive). */
  onHeartbeat(cb: (info: { ts: number; state?: string }) => void): { dispose: () => void }
}

interface AdopterEvent<T> {
  emit(value: T): void
  subscribe(cb: (value: T) => void): () => void
}

function makeEvent<T>(): AdopterEvent<T> {
  const subs = new Set<(value: T) => void>()
  return {
    emit(value: T): void {
      for (const cb of subs) cb(value)
    },
    subscribe(cb: (value: T) => void): () => void {
      subs.add(cb)
      return () => subs.delete(cb)
    },
  }
}

/**
 * Open an adopter against the PTY socket at `socketPath`. Returns
 * immediately; the connection happens asynchronously and any data
 * sent via `write/resize/kill` before connect completes is queued.
 */
export function createPtyAdopter(socketPath: string): PtyAdopter {
  const onDataEvent = makeEvent<Buffer>()
  const onExitEvent = makeEvent<{ exitCode: number; signal?: string }>()
  const onHeartbeatEvent = makeEvent<{ ts: number; state?: string }>()

  let socket: Socket | undefined
  let pendingFrames: Buffer[] = []
  let pendingBytes = 0
  let connected = false
  let disposed = false
  let attempt = 0
  let reconnectTimer: NodeJS.Timeout | undefined
  let drainTimer: NodeJS.Timeout | undefined
  let backpressureTimer: NodeJS.Timeout | undefined
  let sigkillTimer: NodeJS.Timeout | undefined
  let helloPid = 0
  let helloVersion = ''

  function clearTimers(): void {
    if (drainTimer) {
      clearTimeout(drainTimer)
      drainTimer = undefined
    }
    if (backpressureTimer) {
      clearTimeout(backpressureTimer)
      backpressureTimer = undefined
    }
  }

  function notifyExit(exitCode: number, signal?: string): void {
    if (disposed) return
    disposed = true
    if (sigkillTimer) {
      clearTimeout(sigkillTimer)
      sigkillTimer = undefined
    }
    clearTimers()
    socket?.destroy()
    socket = undefined
    onExitEvent.emit({ exitCode, signal })
  }

  function enqueueOrSend(frame: Buffer): void {
    if (socket && !socket.destroyed) {
      const ok = socket.write(frame)
      if (!ok) {
        // backpressure — schedule destroy if drain doesn't fire in 10s
        // (ant XW3 = 10000), and immediate destroy if the buffer crosses
        // CLIENT_BACKPRESSURE_BYTES (ant GXK).
        if (!drainTimer) {
          drainTimer = setTimeout(() => {
            drainTimer = undefined
            socket?.destroy()
          }, 10_000)
          drainTimer.unref()
        }
        if (
          !backpressureTimer &&
          socket.writableLength > CLIENT_BACKPRESSURE_BYTES
        ) {
          backpressureTimer = setTimeout(() => {
            backpressureTimer = undefined
            if (
              socket &&
              !socket.destroyed &&
              socket.writableLength > CLIENT_BACKPRESSURE_BYTES
            ) {
              clearTimers()
              socket.destroy()
            }
          }, 50) // ant PW3 = 50ms grace
          backpressureTimer.unref()
        }
      }
      return
    }
    // Not connected — queue. Drop oldest if over cap.
    if (pendingBytes + frame.length > QUEUE_CAP_BYTES) return
    pendingFrames.push(frame)
    pendingBytes += frame.length
  }

  function handleFrame(frame: { kind: number; payload?: Buffer; ctrl?: CtrlFrame }): void {
    if (frame.kind === DATA_TAG && frame.payload) {
      onDataEvent.emit(frame.payload)
    } else if (frame.kind === CTRL_TAG && frame.ctrl) {
      const c = frame.ctrl
      if (c.t === 'hello') {
        helloPid = c.replPid
        helloVersion = c.version
      } else if (c.t === 'live') {
        // No-op; live just signals that ring buffer replay is done.
      } else if (c.t === 'exit') {
        notifyExit(c.code, c.signal)
      } else if (c.t === 'heartbeat') {
        onHeartbeatEvent.emit({ ts: c.ts, state: c.state })
      }
    }
  }

  function tryConnect(): void {
    if (disposed || connected) return
    const sock = connect(socketPath)
    let opened = false
    sock.on('error', err => {
      if ((err as NodeJS.ErrnoException).code === 'ENOENT') {
        // Socket file is gone — host died or never started.
        // Bubble up as exit so the caller can give up. ant 4704.js:95
        // would retry here; daemon-less ccb has no host to wait for.
        if (!opened) notifyExit(-1, 'ENOENT')
      }
      sock.destroy()
    })
    sock.once('close', () => {
      if (socket === sock) {
        socket = undefined
        connected = false
        clearTimers()
      }
      if (!disposed && !opened) {
        // Connection failed before opening — schedule retry.
        scheduleReconnect()
      }
    })
    sock.once('connect', () => {
      opened = true
      connected = true
      attempt = 0
      socket = sock
      sock.on('drain', clearTimers)
      // Flush queued frames.
      const queued = pendingFrames
      pendingFrames = []
      pendingBytes = 0
      for (const f of queued) enqueueOrSend(f)
    })
    const decoder = createFrameDecoder(handleFrame, () => sock.destroy())
    sock.on('data', decoder)
  }

  function scheduleReconnect(): void {
    if (disposed || reconnectTimer) return
    if (attempt >= MAX_RECONNECT_ATTEMPTS) {
      notifyExit(-1, 'reconnect-exhausted')
      return
    }
    const delay =
      RECONNECT_BACKOFF_MS[Math.min(attempt, RECONNECT_BACKOFF_MS.length - 1)]!
    attempt++
    reconnectTimer = setTimeout(() => {
      reconnectTimer = undefined
      tryConnect()
    }, delay)
    reconnectTimer.unref()
  }

  // Kick off the initial connection.
  tryConnect()

  return {
    replPid: () => helloPid,
    replVersion: () => helloVersion,
    write(buf: Buffer): void {
      if (disposed) return
      // Frame body cap is 1 MiB; chunk if larger.
      const chunkSize = FRAME_SIZE_CAP - 1
      for (let i = 0; i < buf.length; i += chunkSize) {
        enqueueOrSend(encodeDataFrame(buf.subarray(i, i + chunkSize)))
      }
    },
    resize(cols: number, rows: number): void {
      if (disposed) return
      enqueueOrSend(encodeCtrlFrame({ t: 'resize', cols, rows }))
    },
    kill(sig: 'SIGTERM' | 'SIGKILL'): void {
      if (disposed) return
      enqueueOrSend(encodeCtrlFrame({ t: 'kill', sig }))
      if (sig === 'SIGTERM') {
        if (sigkillTimer) clearTimeout(sigkillTimer)
        sigkillTimer = setTimeout(() => {
          sigkillTimer = undefined
          if (!disposed) {
            enqueueOrSend(encodeCtrlFrame({ t: 'kill', sig: 'SIGKILL' }))
          }
        }, SIGTERM_GRACE_MS)
        sigkillTimer.unref()
      }
    },
    dispose(): void {
      if (disposed) return
      disposed = true
      if (reconnectTimer) {
        clearTimeout(reconnectTimer)
        reconnectTimer = undefined
      }
      if (sigkillTimer) {
        clearTimeout(sigkillTimer)
        sigkillTimer = undefined
      }
      clearTimers()
      socket?.destroy()
      socket = undefined
    },
    onData(cb): { dispose: () => void } {
      const off = onDataEvent.subscribe(cb)
      return { dispose: off }
    },
    onExit(cb): { dispose: () => void } {
      const off = onExitEvent.subscribe(cb)
      return { dispose: off }
    },
    onHeartbeat(cb): { dispose: () => void } {
      const off = onHeartbeatEvent.subscribe(cb)
      return { dispose: off }
    },
  }
}

/**
 * Per-worker classifier orchestrator — ant 3921.js Wp7/Gp7 + ZB5.
 *
 * For each WorkerVm:
 *   1. Subscribe to ring writes (via WorkerVm.on('write')).
 *   2. Every CLASSIFIER_TICK_MS, read ring tail and run preclassify →
 *      heuristic → llm pipeline.
 *   3. Write state.json + append timeline.jsonl on state change.
 *   4. Emit tengu_bg_classify with full ant payload.
 *
 * Stops orchestration on vm.settle.
 *
 * Gate: THYROX_CODE_BG_CLASSIFIER=1 (env var). LLM engine additionally
 * requires THYROX_CODE_BG_CLASSIFIER_ENGINE=llm; default is heuristic
 * (no API spend).
 *
 * @dynamicRequire
 */

import { join } from 'node:path'

import { getConfigHomeDir } from '@thyrox/config/env/configHome.js'
import { logEvent } from '@thyrox/local-observability'
import { readJobState } from '@thyrox/agent/background/fleet/fleetStore.js'
import { generateJobName } from '@thyrox/agent/background/fleet/generateJobName.js'
import type { WorkerVm } from '../workerVm.js'
import { closingShape } from './heuristic.js'
import { classify } from './llmClient.js'
import { isTerminalState, type WorkerState, type WorkerStateFile } from './state.js'
import { appendTimeline, readState, writeState } from './stateFile.js'

const CLASSIFIER_TICK_MS = 5000
const CLASSIFIER_DEBOUNCE_MS = 1500

interface OrchestratorState {
  vm: WorkerVm
  intent?: string
  startedAt: number
  prevState: WorkerState
  prevDetail: string
  prevTempo: 'active' | 'idle' | 'blocked'
  lastClassifyAt: number
  pendingTick: NodeJS.Timeout | null
  intervalTimer: NodeJS.Timeout | null
  stopped: boolean
  /** Cumulative tokens across all LLM calls for this worker. */
  tokens: { input: number; output: number; cacheRead: number; cacheCreation: number }
}

const orchestrators = new Map<string, OrchestratorState>()

export function isClassifierEnabled(): boolean {
  return process.env.THYROX_CODE_BG_CLASSIFIER === '1'
}

export function getClassifierEngine(): 'heuristic' | 'llm' {
  return process.env.THYROX_CODE_BG_CLASSIFIER_ENGINE === 'llm' ? 'llm' : 'heuristic'
}

/** ant fp7 — record once per process, on first orchestrator start. */
let configEmitted = false
function emitConfigOnce(): void {
  if (configEmitted) return
  configEmitted = true
  logEvent('tengu_bg_classifier_config', {
    useSmallFastModel: 'true',
    disableThinking: 'true',
    engine: getClassifierEngine(),
  })
}

export function startOrchestrator(vm: WorkerVm, intent?: string): void {
  if (!isClassifierEnabled()) return
  const short = vm.short
  if (orchestrators.has(short)) return
  emitConfigOnce()
  const state: OrchestratorState = {
    vm,
    intent,
    startedAt: Date.now(),
    prevState: 'working',
    prevDetail: '',
    prevTempo: 'active',
    lastClassifyAt: 0,
    pendingTick: null,
    intervalTimer: null,
    stopped: false,
    tokens: { input: 0, output: 0, cacheRead: 0, cacheCreation: 0 },
  }
  // Seed prev from existing state file (so daemon restart preserves continuity).
  const existing = readState(short)
  if (existing) {
    state.prevState = existing.state
    state.prevDetail = existing.detail
    state.prevTempo = existing.tempo
    state.tokens = existing.tokens ?? state.tokens
  } else {
    // Initial state file write — captures intent + cwd + cliVersion.
    const now = new Date().toISOString()
    const initial: WorkerStateFile = {
      state: 'working',
      detail: 'starting',
      tempo: 'active',
      createdAt: now,
      updatedAt: now,
      cwd: vm.getRecord().cwd,
      cliVersion: vm.getRecord().cliVersion,
      intent,
      backend: 'daemon',
    }
    writeState(short, initial)
  }
  orchestrators.set(short, state)

  const triggerClassify = (): void => {
    if (state.stopped) return
    if (state.pendingTick) return
    const elapsed = Date.now() - state.lastClassifyAt
    const wait = Math.max(0, CLASSIFIER_DEBOUNCE_MS - elapsed)
    state.pendingTick = setTimeout(() => {
      state.pendingTick = null
      void runClassify(state).catch(() => {})
    }, wait)
    state.pendingTick.unref()
  }

  // Ring write listener (fires on every PTY chunk).
  vm.on('write', triggerClassify)
  // Periodic tick to catch stalls + cron-like classification.
  state.intervalTimer = setInterval(triggerClassify, CLASSIFIER_TICK_MS)
  state.intervalTimer.unref()
  // Settle listener stops orchestrator.
  vm.once('settled', () => stopOrchestrator(short))
}

export function stopOrchestrator(short: string): void {
  const state = orchestrators.get(short)
  if (!state) return
  state.stopped = true
  if (state.pendingTick) clearTimeout(state.pendingTick)
  if (state.intervalTimer) clearInterval(state.intervalTimer)
  orchestrators.delete(short)
  // Final state write — mark firstTerminalAt if state is terminal.
  const cur = readState(short)
  if (cur && !cur.firstTerminalAt && isTerminalState(cur.state)) {
    writeState(short, { ...cur, firstTerminalAt: new Date().toISOString() })
  }
}

async function runClassify(state: OrchestratorState): Promise<void> {
  if (state.stopped) return
  state.lastClassifyAt = Date.now()
  const ringChunks = state.vm.getRingSnapshot()
  const text = Buffer.concat(ringChunks).toString('utf8')
  if (!text.trim()) return

  const cur = readState(state.vm.short)
  const minsInState = cur
    ? Math.round((Date.now() - Date.parse(cur.updatedAt)) / 60_000)
    : 0
  const result = await classify({
    text,
    prevState: state.prevState,
    latestAsk: state.intent,
    toolSummary: undefined,
    minsInState,
    engine: getClassifierEngine(),
  })

  // Accumulate tokens.
  state.tokens.input += result.tokens.input
  state.tokens.output += result.tokens.output
  state.tokens.cacheRead += result.tokens.cacheRead
  state.tokens.cacheCreation += result.tokens.cacheCreation

  const stateChanged = cur === null || cur.state !== result.state
  const now = new Date().toISOString()
  const next: WorkerStateFile = {
    state: result.state,
    detail: result.detail,
    tempo: result.tempo,
    needs: result.needs,
    output: result.output,
    classifySource: result.source,
    firstTerminalAt:
      cur?.firstTerminalAt ??
      (isTerminalState(result.state) ? now : undefined),
    createdAt: cur?.createdAt ?? now,
    updatedAt: now,
    cwd: state.vm.getRecord().cwd,
    cliVersion: state.vm.getRecord().cliVersion,
    intent: state.intent ?? cur?.intent,
    backend: 'daemon',
    sessionId: cur?.sessionId,
    tokens: state.tokens,
  }
  writeState(state.vm.short, next)
  if (stateChanged) {
    appendTimeline(state.vm.short, {
      at: now,
      state: result.state,
      detail: result.detail,
      text: text.slice(-4000),
    })
  }

  logEvent('tengu_bg_classify', {
    short: state.vm.short,
    engine: result.engine,
    branch: result.branch ?? 'none',
    closingShape: closingShape(text),
    prevState: state.prevState,
    newState: result.state,
    stateChanged: String(stateChanged),
    minsInPrevState: String(minsInState),
    durationMs: String(result.durationMs),
    tailChars: String(text.length),
    ...(result.engine === 'llm' && {
      attempts: String(result.attempts),
      inputTokens: String(result.tokens.input),
      outputTokens: String(result.tokens.output),
      cacheReadInputTokens: String(result.tokens.cacheRead),
      cacheCreationInputTokens: String(result.tokens.cacheCreation),
    }),
  })

  // Emit agent_terminal once when entering terminal state.
  if (
    isTerminalState(result.state) &&
    !cur?.firstTerminalAt
  ) {
    logEvent('tengu_bg_agent_terminal', {
      short: state.vm.short,
      outcome: result.state,
      durationMs: String(Date.now() - state.startedAt),
      classifySource: result.source,
    })
  }

  state.prevState = result.state
  state.prevDetail = result.detail
  state.prevTempo = result.tempo

  // Source: ant 3991.js — namer trigger from the classifier post-LLM
  // pass:
  //   if (!f?.name && C && $==="llm" && !H.nameInFlight) {
  //     let m = O.filter(x => !x.isApiErrorMessage).map(rE).find(Boolean)
  //     let p = m ? "" : yy8(O)
  //     let S = f3H(X3(m ?? (p ? `[calling ${p}]` : "")), 500)
  //     H.nameInFlight = !0
  //     Vq3(Y, C, S).catch(vH).finally(() => { H.nameInFlight = !1 })
  //   }
  //
  // Where `f` is the FleetJobState (we re-read after writing to pick up
  // the freshly persisted intent), `$` is the classifier source, `C` is
  // the user prompt (state.intent), and `S` is the agent's first text
  // message tail (we approximate with the ring tail used by classify).
  //
  // The namer is fire-once per worker lifetime (via attempted Set in
  // namer.ts), so spamming this branch is safe — it self-debounces.
  if (result.source === 'llm') {
    const jobsRoot = join(getConfigHomeDir(), 'jobs', state.vm.short)
    const fleetState = await readJobState(jobsRoot).catch(() => null)
    const intent =
      fleetState?.intent ?? state.intent ?? fleetState?.initialPrompt
    if (
      fleetState !== null &&
      (fleetState.name === undefined || fleetState.name === '') &&
      typeof intent === 'string' &&
      intent.length > 0
    ) {
      void generateJobName({
        short: state.vm.short,
        userMsg: intent,
        // Use the LLM detail as a compact agent-tail proxy — full text
        // would blow past Vq3's 300-char cap and ant truncates anyway.
        agentTail: result.detail ?? '',
      }).catch(() => undefined)
    }
  }
}

/** Test/inspection helper. */
export function _orchestratorCount(): number {
  return orchestrators.size
}

