42	/** ant iYH — true if `_` index is inside an open code fence. */
43	export function isInCodeFence(text: string, idx: number): boolean {
44	  let openMarker: string | null = null
45	  let openLen = 0
46	  let pos = 0
47	  while (pos < idx) {
48	    const tickAt = text.indexOf('```', pos)
49	    const tildeAt = text.indexOf('~~~', pos)
50	    const fenceAt =
51	      tickAt === -1 ? tildeAt : tildeAt === -1 ? tickAt : Math.min(tickAt, tildeAt)
52	    if (fenceAt === -1 || fenceAt >= idx) break
53	    const marker = text[fenceAt]!
54	    let leftIdx = fenceAt - 1
55	    let leftCount = 0
56	    while (leftIdx >= 0 && text[leftIdx] === ' ' && leftCount < 3) {
57	      leftIdx--
58	      leftCount++
59	    }
60	    const atLineStart = leftIdx < 0 || text[leftIdx] === '\n'
61	    let runLen = 3
62	    pos = fenceAt + 3
63	    while (text[pos] === marker) {
64	      pos++
65	      runLen++
66	    }
67	    if (!atLineStart) continue
68	    if (openMarker === null) {
69	      openMarker = marker
70	      openLen = runLen
71	    } else if (openMarker === marker && runLen >= openLen) {
72	      openMarker = null
73	      openLen = 0
74	    }
75	  }
76	  return openMarker !== null
77	}
