289	/** ant tm7 — describe the closing-shape so LLM prompt can include it. */
290	export function closingShape(text: string): string {
291	  const trimmed = text.trim()
292	  if (!trimmed) return 'empty'
293	  if (isInCodeFence(trimmed, trimmed.length)) return 'code-fence'
294	  const tail = trimmed.slice(-800)
295	  const tailOffset = trimmed.length - tail.length
296	  for (const m of tail.matchAll(/(?:^|\n)\s*result:\s*\S/gi)) {
297	    if (!isInCodeFence(trimmed, tailOffset + m.index!)) return 'result-line'
298	  }
299	  for (const m of tail.matchAll(/(?:^|\n)\s*failed:\s*\S/gi)) {
300	    if (!isInCodeFence(trimmed, tailOffset + m.index!)) return 'failed-line'
301	  }
302	  if (/[?\uFF1F]\s*$/.test(trimmed)) return 'trailing-q'
303	  const last200 = trimmed.slice(-200)
304	  if (/(?:^|\n)\s*(?:[-*\u2022]|\d+\.|[|])\s/.test(last200)) return 'list-or-table'
305	  return 'declarative'
