308	/** ant GJ_ — merge LLM output with prev state, default-fill. */
309	const VALID_STATES = new Set<WorkerState>(['working', 'blocked', 'done', 'failed'])
310	const TERMINAL_TEMPO_LOCK = new Set<WorkerState>(['done', 'failed', 'stopped', 'crashed'])
311	
312	export function mergeWithPrev(
313	  raw: { state?: unknown; detail?: unknown; tempo?: unknown; needs?: unknown; output?: unknown },
314	  prev: WorkerState,
315	  fallback: ClassifierResult | null,
316	): { state: WorkerState; detail: string; tempo: 'active' | 'idle' | 'blocked'; needs?: string; output: Record<string, string> } {
317	  const rawState = typeof raw.state === 'string' && raw.state ? (raw.state as WorkerState) : undefined
318	  const state: WorkerState =
319	    rawState && VALID_STATES.has(rawState) ? rawState : (fallback?.state ?? prev)
320	  const rawTempo = typeof raw.tempo === 'string' && raw.tempo ? raw.tempo : undefined
321	  const tempo =
322	    TERMINAL_TEMPO_LOCK.has(state)
323	      ? 'idle'
324	      : rawTempo === 'active' || rawTempo === 'idle' || rawTempo === 'blocked'
325	        ? rawTempo
326	        : (fallback?.tempo ?? 'active')
