328	  const rawOut = (raw.output as Record<string, unknown> | undefined) ?? fallback?.output
329	  if (rawOut && typeof rawOut === 'object') {
330	    for (const [k, v] of Object.entries(rawOut)) {
331	      if (typeof v === 'string' && v && k === 'result') {
332	        output[k] = truncate(v, MAX_DETAIL_CHARS)
