347	/** ant qp7 — strip ```json fence + extract JSON object from LLM text. */
348	export function parseLlmJson(text: string): Record<string, unknown> | null {
349	  const stripped = text.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/, '')
350	  const first = stripped.indexOf('{')
351	  const last = stripped.lastIndexOf('}')
352	  if (first < 0 || last < 0) return null
353	  try {
354	    return JSON.parse(stripped.slice(first, last + 1)) as Record<string, unknown>
355	  } catch {
356	    return null
357	  }
